-- Documents (specification 7.2, 8, ADR-030). Ids are UUID version 7, generated by the application.
-- The T3 column supersedes_document_id is added by the phase that builds it.
CREATE TABLE document (
    id                    uuid        PRIMARY KEY,
    -- Users are never deleted (AUTH-11); an account that owns documents cannot be removed.
    owner_id              uuid        NOT NULL REFERENCES app_user (id) ON DELETE RESTRICT,
    title                 text        NOT NULL,
    description           text,
    category              text,
    original_filename     text        NOT NULL,
    content_type          text        NOT NULL,
    size_bytes            bigint      NOT NULL,
    sha256                text        NOT NULL,
    storage_key           text        NOT NULL,
    status                text        NOT NULL,
    failure_code          text,
    failure_message       text,
    page_count            integer,
    chunk_count           integer,
    document_date         date,
    archived              boolean     NOT NULL,
    processing_attempts   integer     NOT NULL,
    processing_started_at timestamptz,
    indexed_at            timestamptz,
    embedding_model       text,
    embedding_dim         integer,
    row_version           bigint      NOT NULL,
    created_at            timestamptz NOT NULL,
    updated_at            timestamptz NOT NULL,
    -- DOC-2: the same file uploaded again by the same owner is a duplicate. This index also
    -- serves the lookups by owner.
    CONSTRAINT document_owner_id_sha256_key UNIQUE (owner_id, sha256),
    CONSTRAINT document_storage_key_key UNIQUE (storage_key),
    CONSTRAINT document_title_not_blank CHECK (btrim(title) <> ''),
    CONSTRAINT document_size_bytes_check CHECK (size_bytes > 0),
    CONSTRAINT document_sha256_check CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    CONSTRAINT document_processing_attempts_check CHECK (processing_attempts >= 0),
    CONSTRAINT document_status_check CHECK (status IN ('UPLOADED', 'PROCESSING', 'INDEXED', 'FAILED')),
    -- Specification 8.3, with PROCESSING_TIMEOUT from ADR-030.
    CONSTRAINT document_failure_code_check CHECK (failure_code IN (
        'UNSUPPORTED_TYPE', 'EMPTY', 'ENCRYPTED', 'NO_TEXT_LAYER', 'TOO_MANY_PAGES',
        'EXTRACTION_ERROR', 'EMBEDDING_ERROR', 'PROCESSING_TIMEOUT', 'INTERNAL')),
    -- A failed document always says why, and no other document carries a failure code.
    CONSTRAINT document_failure_code_matches_status CHECK ((status = 'FAILED') = (failure_code IS NOT NULL))
);

-- The ingestion worker (Phase 3) finds its work by status.
CREATE INDEX document_status_idx ON document (status);
